import {mock} from 'node:test';import assert from 'node:assert/strict';import {controlsFingerprint} from '../../api/_instore-catalogue.js';
const calls=[];let generation='1';const client={async rpc(name,args){calls.push({name,args});if(name==='instore_catalogue_claim_refresh')return {data:true,error:null};if(name==='instore_website_content_read_v1')return {data:{generation,overrides:[],placements:[]},error:null};if(name==='instore_catalogue_stage')return {data:null,error:null};if(name==='instore_catalogue_commit'){assert.equal(args.p_controls_fingerprint,controlsFingerprint(new Map(),new Map(),'1'));assert.equal(generation,'2');return {data:{refreshed_at:new Date().toISOString(),tiles:[]},error:null};}throw Error('Unexpected RPC '+name);}};
mock.module('../../api/extended-range.js',{namedExports:{stockClient:()=>client,loadLiveInstoreCatalogue:async()=>{assert.ok(calls.some(c=>c.name==='instore_website_content_read_v1'));generation='2';return {products:[{sku:'SYNTHETIC',name:'SAMPLE',category:'household'}],imageControls:new Map(),listingControls:new Map()};}}});globalThis.fetch=()=>{throw Error('External network denied');};process.env.CRON_SECRET='synthetic-refresh-fixture-only';const {default:handler}=await import('../../api/instore-catalogue-refresh.js');const response=()=>({setHeader(){},status(n){this.code=n;return this;},json(v){this.body=v;return this;}});let res=response();await handler({method:'POST',headers:{},query:{}},res);assert.equal(res.code,401);assert.equal(calls.length,0);res=response();await handler({method:'POST',headers:{authorization:'Bearer synthetic-refresh-fixture-only'},query:{}},res);assert.equal(res.code,200);assert.equal(res.body.refreshed,true);assert.equal(calls.filter(c=>c.name==='instore_catalogue_commit').length,1);console.log(JSON.stringify({passed:true,sourceGeneration:generation,committedGeneration:'1'}));
